#include <stdio.h>

int main() {
    int notes[5] = {12, 15, 9, 18, 11};
    int taille = 5;
    int somme = 0;

    for (int i = 0; i < taille; i++) {
        somme += notes[i];
    }

    printf("Moyenne : %.1f\n", (double)somme / taille);
    printf("Premier élément : %d\n", notes[0]);
    printf("Dernier élément : %d\n", notes[taille - 1]);
    return 0;
}
